"""PDF119 printed 229–230: Unit 6 questions 6.19–6.28 (end of Unit 6)."""
from class12_statistics_common import Builder, save

b = Builder()
Q = lambda n, e, u, p: b.p(f'{n} {e}', f'{n} {u}', f'{n} {p}')
Q('6.19', 'If n = 50, Σx = 2163, Σx² = 144949.6. Compute a 99% confidence interval for μ.', 'اگر n = 50، Σx = 2163، Σx² = 144949.6 ہو تو μ کے لیے 99% اعتماد کا وقفہ معلوم کریں۔', 'که n = 50، Σx = 2163، Σx² = 144949.6 وي، د μ لپاره 99% د باور واټن محاسبه کړئ.')
Q('6.20', 'A random sample of size $n_1=36$ taken from a normal population with a variance $\\sigma_1^2=9$ has mean $\\overline{x}_1=75$. A second random sample of size $n_2=25$ taken from a different population with a variance $\\sigma_2^2=25$ has a mean $\\overline{x}_2=70$. Find a 98% confidence interval for $\\mu_1-\\mu_2$.', '$\\sigma_1^2=9$ تغیر والی نارمل آبادی سے لیے گئے $n_1=36$ سائز کے تصادفی نمونے کا اوسط $\\overline{x}_1=75$ ہے۔ $\\sigma_2^2=25$ تغیر والی ایک مختلف آبادی سے لیے گئے $n_2=25$ سائز کے دوسرے تصادفی نمونے کا اوسط $\\overline{x}_2=70$ ہے۔ $\\mu_1-\\mu_2$ کے لیے 98% اعتماد کا وقفہ معلوم کریں۔', 'د $\\sigma_1^2=9$ واریانس لرونکي نورمال نفوس څخه اخیستل شوې د $n_1=36$ اندازې تصادفي نمونه منځنی $\\overline{x}_1=75$ لري. د $\\sigma_2^2=25$ واریانس لرونکي بل نفوس څخه اخیستل شوې د $n_2=25$ اندازې دویمه تصادفي نمونه منځنی $\\overline{x}_2=70$ لري. د $\\mu_1-\\mu_2$ لپاره 98% د باور واټن پیدا کړئ.')
Q('6.21', 'The number of accidents per day in two cities was observed and the following information was obtained:', 'دو شہروں میں فی دن حادثات کی تعداد کا مشاہدہ کیا گیا اور درج ذیل معلومات حاصل ہوئیں:', 'په دوو ښارونو کې په ورځ کې د پېښو شمېر وکتل شو او لاندې معلومات ترلاسه شول:')
b.table('stat12-t-q6-21', ['Description', 'city-A', 'city-B'], [['Numbers of days', '144', '100'], ['Mean number of accidents', '4.5', '5.4'], ['Standard deviation', '1.2', '1.5']],
        ['تفصیل', 'شہر-A', 'شہر-B'], ['تشریح', 'ښار-A', 'ښار-B'],
        [['دنوں کی تعداد', '144', '100'], ['حادثات کی اوسط تعداد', '4.5', '5.4'], ['معیاری انحراف', '1.2', '1.5']],
        [['د ورځو شمېر', '144', '100'], ['د پېښو منځنی شمېر', '4.5', '5.4'], ['معیاري انحراف', '1.2', '1.5']])
b.p('Estimate 95% confidence interval for the difference between the mean accidents of the two cities.', 'دونوں شہروں کے اوسط حادثات کے فرق کے لیے 95% اعتماد کا وقفہ تخمین کریں۔', 'د دوو ښارونو د منځنیو پېښو د توپیر لپاره 95% د باور واټن اټکل کړئ.')
Q('6.22', 'When it is appropriate to use t-distribution instead of the Z-distribution to construct confidence interval for the population mean or difference of population means?', 'آبادی کے اوسط یا آبادیوں کے اوسطوں کے فرق کے لیے اعتماد کا وقفہ بنانے کے لیے Z-تقسیم کی جگہ t-تقسیم کا استعمال کب موزوں ہے؟', 'د نفوس د منځني یا د نفوسونو د منځنیو د توپیر لپاره د باور واټن د جوړولو لپاره د Z-وېش پر ځای د t-وېش کارول کله مناسب دي؟')
Q('6.23', 'A sample of 10 measurements of the diameter of a spare gave a mean $\\overline{x}=4.38$ inches and a standard deviation s = 0.06 inches. Find a 95% confidence interval for the actual diameter.', 'ایک فاضل پرزے کے قطر کی 10 پیمائشوں کے نمونے نے اوسط $\\overline{x}=4.38$ انچ اور معیاری انحراف s = 0.06 انچ دیا۔ اصل قطر کے لیے 95% اعتماد کا وقفہ معلوم کریں۔', 'د یوه اضافي پرزې د قطر د 10 اندازو نمونې منځنی $\\overline{x}=4.38$ انچه او معیاري انحراف s = 0.06 انچه ورکړ. د اصلي قطر لپاره 95% د باور واټن پیدا کړئ.')
Q('6.24', 'A random sample of 12 ball bearings has weights in grams as 31.4, 33.1, 35.9, 34.7, 33.4, 34.5, 35, 32.5, 36.9, 36.4, 35.8, 33.2. Find a 90% confidence interval for the mean weight of the population from which these weights were drawn.', '12 بال بیرنگز کے تصادفی نمونے کے وزن گرام میں یہ ہیں: 31.4، 33.1، 35.9، 34.7، 33.4، 34.5، 35، 32.5، 36.9، 36.4، 35.8، 33.2۔ اس آبادی کے اوسط وزن کے لیے 90% اعتماد کا وقفہ معلوم کریں جس سے یہ وزن لیے گئے۔', 'د 12 بال بېرنګونو تصادفي نمونه په ګرامو کې دا وزنونه لري: 31.4، 33.1، 35.9، 34.7، 33.4، 34.5، 35، 32.5، 36.9، 36.4، 35.8، 33.2. د هغه نفوس د منځني وزن لپاره 90% د باور واټن پیدا کړئ چې دا وزنونه ترې اخیستل شوي.')
Q('6.25', 'The following summary statistics were recorded from independent random samples drawn from two populations:', 'دو آبادیوں سے لیے گئے آزاد تصادفی نمونوں سے درج ذیل خلاصہ شماریے ریکارڈ کیے گئے:', 'له دوو نفوسونو څخه د اخیستل شویو خپلواکو تصادفي نمونو څخه لاندې لنډیز احصاییې ثبت شوې:')
b.table('stat12-t-q6-25', ['', '$n$', '$\\overline{x}$', '$s^2$'], [['Sample A', '10', '74', '60'], ['Sample B', '13', '81', '40']], ['', '$n$', '$\\overline{x}$', '$s^2$'], ['', '$n$', '$\\overline{x}$', '$s^2$'],
        [['نمونہ A', '10', '74', '60'], ['نمونہ B', '13', '81', '40']], [['نمونه A', '10', '74', '60'], ['نمونه B', '13', '81', '40']])
b.p('Construct a 99% confidence interval for $\\mu_A-\\mu_B$', '$\\mu_A-\\mu_B$ کے لیے 99% اعتماد کا وقفہ بنائیں', 'د $\\mu_A-\\mu_B$ لپاره 99% د باور واټن جوړ کړئ')
Q('6.26', 'Find a 95% confidence interval for p if 24 heads are obtained in 40 tosses of a coin.', 'اگر ایک سکے کو 40 بار اچھالنے میں 24 چِت آئیں تو p کے لیے 95% اعتماد کا وقفہ معلوم کریں۔', 'که د یوې سکې په 40 اچولو کې 24 سرونه ترلاسه شي، د p لپاره 95% د باور واټن پیدا کړئ.')
Q('6.27', 'In a survey carried out in a large city 170 housewives out of a random sample of 250 preferred Lipton brand of tea. Find a 95% confidence interval for the percentage of all housewives in the city preferring Lipton brand of tea.', 'ایک بڑے شہر میں کیے گئے سروے میں 250 کے تصادفی نمونے میں سے 170 خاتونِ خانہ نے لپٹن برانڈ کی چائے کو ترجیح دی۔ شہر کی ان تمام خواتینِ خانہ کے فیصد کے لیے 95% اعتماد کا وقفہ معلوم کریں جو لپٹن برانڈ کی چائے کو ترجیح دیتی ہیں۔', 'په یوه لوی ښار کې په ترسره شوې سروې کې د 250 تصادفي نمونې له جملې څخه 170 کورنیو مېرمنو د لیپټن برانډ چای غوره کړ. په ښار کې د هغو ټولو کورنیو مېرمنو د سلنې لپاره 95% د باور واټن پیدا کړئ چې د لیپټن برانډ چای غوره کوي.')
Q('6.28', 'Independent random samples of $n_1=800$ and $n_2=640$ observations were selected from binomial populations 1 and 2, and $X_1=337$, $X_2=374$ successes were observed. Find a 90% confidence interval for the difference $(p_1-p_2)$ in the two population proportions. Interpret the interval.', 'دو رقمی آبادیوں 1 اور 2 سے $n_1=800$ اور $n_2=640$ مشاہدات کے آزاد تصادفی نمونے منتخب کیے گئے، اور $X_1=337$، $X_2=374$ کامیابیاں دیکھی گئیں۔ دونوں آبادیوں کے تناسبوں کے فرق $(p_1-p_2)$ کے لیے 90% اعتماد کا وقفہ معلوم کریں۔ وقفے کی تشریح کریں۔', 'له 1 او 2 بینومیل نفوسونو څخه د $n_1=800$ او $n_2=640$ مشاهدو خپلواکې تصادفي نمونې وټاکل شوې، او $X_1=337$، $X_2=374$ بریاوې ولیدل شوې. د دوو نفوسونو د تناسبونو د توپیر $(p_1-p_2)$ لپاره 90% د باور واټن پیدا کړئ. واټن تفسیر کړئ.')
rec = b.build('stat12-u6-exercise-c', 'Unit 6 Exercise — questions 6.19 to 6.28', 'یونٹ 6 مشق — سوالات 6.19 تا 6.28', 'واحد 6 تمرین — پوښتنې 6.19 تر 6.28', 119, [229, 230])

if __name__ == '__main__':
    save(119, [(6, rec)], complete_units=[6])
